import { signInWithEmailAndPassword, signOut } from 'firebase/auth';
import { useState } from 'react';
import { Navigate, useNavigate } from 'react-router-dom';
import PageLayout from '../components/PageLayout';
import { auth } from '../firebase';
import SectionHeading from '../components/shared/SectionHeading';

const GOV_USERNAME = 'admin';
const GOV_EMAIL = process.env.REACT_APP_GOV_ADMIN_EMAIL || 'admin@report-and-issue.gov';

const GovernmentLogin = () => {
  const navigate = useNavigate();
  const [officialId, setOfficialId] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  if (auth.currentUser?.email === GOV_EMAIL) {
    return <Navigate to="/gov-home" replace />;
  }

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError('');

    if (!officialId.trim() || !password.trim()) {
      setError('Enter username and password.');
      return;
    }

    setIsSubmitting(true);
    await new Promise((resolve) => setTimeout(resolve, 500));

    if (officialId.trim() !== GOV_USERNAME) {
      setError('Invalid username.');
      setIsSubmitting(false);
      return;
    }

    try {
      if (auth.currentUser && auth.currentUser.email !== GOV_EMAIL) {
        await signOut(auth);
      }

      await signInWithEmailAndPassword(auth, GOV_EMAIL, password);
      navigate('/gov-home', { replace: true });
    } catch (loginError) {
      if (loginError.code === 'auth/invalid-credential') {
        setError('Invalid government password for admin account.');
      } else {
        setError('Government login failed. Verify Firebase account setup and retry.');
      }
      setIsSubmitting(false);
    }
  };

  return (
    <PageLayout>
      <section className="section">
        <div className="container" style={{ maxWidth: '560px' }}>
          <article className="card">
            <SectionHeading
              title="Government Login"
              subtitle="Use your official PM POSHAN credentials to access request approval and complaint response workflows."
            />
            <p className="helper" style={{ marginTop: '0.5rem' }}>
              Username: <span className="mono">admin</span> | Firebase Email: <span className="mono">{GOV_EMAIL}</span>
            </p>

            <form onSubmit={handleSubmit} style={{ marginTop: '1rem' }}>
              <div className="field-group">
                <label className="field-label">Username</label>
                <input
                  value={officialId}
                  onChange={(event) => setOfficialId(event.target.value)}
                  placeholder="Enter username"
                />
              </div>

              <div className="field-group">
                <label className="field-label">Password</label>
                <input
                  type="password"
                  value={password}
                  onChange={(event) => setPassword(event.target.value)}
                  placeholder="Enter password"
                />
              </div>

              {error ? <p className="error-text">{error}</p> : null}

              <div className="actions-row" style={{ marginTop: '0.9rem' }}>
                <button className="btn" type="submit" disabled={isSubmitting}>
                  {isSubmitting ? 'Signing In...' : 'Sign In'}
                </button>
              </div>
            </form>
          </article>
        </div>
      </section>
    </PageLayout>
  );
};

export default GovernmentLogin;
